PROGRAM EulerProblem89(OUTPUT);

{ Read 1000 valid (but not necessarily minimal) Roman numerals from
  roman.txt, and sum the characters saved by rewriting each in its
  minimal form.

  Parsing: standard left-to-right scan -- add a symbol's value unless it
  is smaller than the symbol immediately following it, in which case
  subtract it (handles both subtractive pairs like IV and repeated units
  like IIII, which this problem's input allows).

  Minimal length: greedy largest-denomination-first replacement is known
  optimal for Roman numerals, so repeatedly subtracting the largest
  denomination that still fits gives the minimal symbol count directly,
  without having to materialize the minimal numeral itself. }

VAR
  f: TEXT;
  s: LSTRING(20);
  i, idx, len, numval, remaining, minLen, totalSaved: INTEGER;
  denomValues: ARRAY [1..13] OF INTEGER;
  denomLens: ARRAY [1..13] OF INTEGER;

FUNCTION CharValue(ch: CHAR): INTEGER;
BEGIN
  CASE ch OF
    'I': CharValue := 1;
    'V': CharValue := 5;
    'X': CharValue := 10;
    'L': CharValue := 50;
    'C': CharValue := 100;
    'D': CharValue := 500;
    'M': CharValue := 1000
  END
END;

BEGIN

reference_continuation:
  denomValues[1] := 1000; denomValues[2] := 900; denomValues[3] := 500;
  denomValues[4] := 400;  denomValues[5] := 100; denomValues[6] := 90;
  denomValues[7] := 50;   denomValues[8] := 40;  denomValues[9] := 10;
  denomValues[10] := 9;   denomValues[11] := 5;  denomValues[12] := 4;
  denomValues[13] := 1;
  denomLens[1] := 1; denomLens[2] := 2; denomLens[3] := 1; denomLens[4] := 2;
  denomLens[5] := 1; denomLens[6] := 2; denomLens[7] := 1; denomLens[8] := 2;
  denomLens[9] := 1; denomLens[10] := 2; denomLens[11] := 1;
  denomLens[12] := 2; denomLens[13] := 1;

  ASSIGN(f, 'roman.txt');
  RESET(f);
  totalSaved := 0;
  WHILE NOT EOF(f) DO
  BEGIN
    READ(f, s);
    READLN(f);
    len := ORD(s.LEN);

    numval := 0;
    i := 1;
    WHILE i <= len DO
    BEGIN
      { AND does not short-circuit here, so i < len must gate the s[i+1]
        access with a nested IF rather than being AND-ed alongside it --
        otherwise the i = len case still evaluates s[len+1]. }
      IF i < len THEN
      BEGIN
        IF CharValue(s[i]) < CharValue(s[i + 1]) THEN
          numval := numval - CharValue(s[i])
        ELSE
          numval := numval + CharValue(s[i])
      END
      ELSE
        numval := numval + CharValue(s[i]);
      i := i + 1
    END;

    remaining := numval;
    minLen := 0;
    idx := 1;
    WHILE idx <= 13 DO
    BEGIN
      WHILE remaining >= denomValues[idx] DO
      BEGIN
        minLen := minLen + denomLens[idx];
        remaining := remaining - denomValues[idx]
      END;
      idx := idx + 1
    END;

    totalSaved := totalSaved + (len - minLen)
  END;
  CLOSE(f);
  WRITELN(totalSaved)
END.
